/**
 * Built-in demonstration clips. All are SYNTHETIC, computer-generated by
 * scripts/make-synthetic-clips.py, original to this repository (MIT).
 *
 * `suggestedZone` is the tray outline drawn by the clip author (not by AI).
 * The user must still review and confirm it before running.
 */
import type { Point } from "./evaluation/types";

export interface SampleClip {
  id: string;
  title: string;
  description: string;
  file: string; // public URL
  publicPath: string; // path under public/
  suggestedPrompt: string;
  targetLabel: string;
  suggestedZone: Point[];
  expected: "PASS" | "FAIL" | "INCONCLUSIVE";
}

const TRAY_ZONE: Point[] = [
  { x: 600, y: 330 },
  { x: 860, y: 330 },
  { x: 860, y: 470 },
  { x: 600, y: 470 },
];

export const SAMPLES: SampleClip[] = [
  {
    id: "synthetic-pass",
    title: "Success case",
    description: "The gripper places the red cube in the blue tray.",
    file: "/samples/synthetic-pass.mp4",
    publicPath: "samples/synthetic-pass.mp4",
    suggestedPrompt: "red cube",
    targetLabel: "blue tray",
    suggestedZone: TRAY_ZONE,
    expected: "PASS",
  },
  {
    id: "synthetic-fail",
    title: "Failure case",
    description: "The gripper drops the cube before it reaches the tray.",
    file: "/samples/synthetic-fail.mp4",
    publicPath: "samples/synthetic-fail.mp4",
    suggestedPrompt: "red cube",
    targetLabel: "blue tray",
    suggestedZone: TRAY_ZONE,
    expected: "FAIL",
  },
  {
    id: "synthetic-occluded",
    title: "Unclear case",
    description: "A panel hides the tray, so the final placement can't be seen.",
    file: "/samples/synthetic-occluded.mp4",
    publicPath: "samples/synthetic-occluded.mp4",
    suggestedPrompt: "red cube",
    targetLabel: "blue tray",
    suggestedZone: TRAY_ZONE,
    expected: "INCONCLUSIVE",
  },
];

export function getSample(id: string): SampleClip | undefined {
  return SAMPLES.find((s) => s.id === id);
}

export function promptSlug(prompt: string): string {
  return prompt.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

/** Relative path of a recorded real-API fixture for (sample, prompt). */
export function fixtureRelPath(sampleId: string, prompt: string): string {
  return `fixtures/recorded/${sampleId}.${promptSlug(prompt)}.json`;
}
